export function translateStaticText(source: string, locale: PublicLocale): string {
  if (locale === "en" || !source.trim()) return source;
  const leading = source.match(/^\s*/)?.[0] ?? "";
  const trailing = source.match(/\s*$/)?.[0] ?? "";
  const value = source.trim();
  const messageKey = (Object.keys(publicMessages.en) as Array<keyof typeof publicMessages.en>).find((key) => publicMessages.en[key] === value);
  const translated = messageKey ? publicMessages[locale][messageKey] : translations[value]?.[locale === "hi" ? 0 : 1] ?? translatePattern(value, locale);
  return translated === value ? source : `${leading}${translated}${trailing}`;
}

function translatePattern(value: string, locale: Exclude<PublicLocale, "en">): string {
  const step = value.match(/^Step (\d+) · (Describe|Locate & attach|Review)$/);
  if (step) {
    const translatedLabel = translations[step[2]]?.[locale === "hi" ? 0 : 1] ?? step[2];
    return locale === "hi" ? `चरण ${step[1]} · ${translatedLabel}` : `Etapa ${step[1]} · ${translatedLabel}`;
  }
  const tracking = value.match(/^Tracking ([\w-]+)$/);
  if (tracking) return locale === "hi" ? `ट्रैकिंग ${tracking[1]}` : `Acompanhando ${tracking[1]}`;
  const grounded = value.match(/^The hotspot's strongest recorded influences are (.+)\. Evidence is (.+?)\.(.*)$/);
  if (grounded) {
    const factors = translateFactorPhrase(grounded[1], locale);
    const confidence = translateFactorPhrase(grounded[2], locale);
    const suffix = grounded[3].trim();
    const translatedSuffix = suffix ? ` ${translateStaticText(suffix, locale)}` : "";
    return locale === "hi" ? `हॉटस्पॉट के सबसे मजबूत दर्ज प्रभाव ${factors} हैं। प्रमाण ${confidence} हैं।${translatedSuffix}` : `As influências registradas mais fortes são ${factors}. As evidências têm ${confidence}.${translatedSuffix}`;
  }
  const grouped = value.match(/^(\d+) privacy-safe requests are grouped under (.+) in (.+)\.$/);
  if (grouped) return locale === "hi" ? `${grouped[3]} में ${grouped[2]} के अंतर्गत ${grouped[1]} गोपनीयता-सुरक्षित अनुरोध समूहित हैं।` : `${grouped[1]} solicitações protegidas estão agrupadas em ${grouped[2]} em ${grouped[3]}.`;
  const backendScore = value.match(/^The backend reports an Action Score of ([\d.]+) and (.+)\.$/);
  if (backendScore) return locale === "hi" ? `बैकएंड ${backendScore[1]} का कार्रवाई स्कोर और ${translateFactorPhrase(backendScore[2], locale)} रिपोर्ट करता है।` : `O backend informa uma pontuação de ação de ${backendScore[1]} e ${translateFactorPhrase(backendScore[2], locale)}.`;
  const confidencePercent = value.match(/^Confidence is ([\d.]+)%\. This is evidence reliability, not certainty that a particular intervention will succeed\.$/);
  if (confidencePercent) return locale === "hi" ? `विश्वसनीयता ${confidencePercent[1]}% है। यह प्रमाण की विश्वसनीयता है, किसी हस्तक्षेप की सफलता की निश्चितता नहीं।` : `A confiança é de ${confidencePercent[1]}%. Isso mede a confiabilidade da evidência, não garante o sucesso de uma intervenção.`;
  const points = value.match(/^(Added|Reduced the component score by) ([\d.]+) points$/);
  if (points) return locale === "hi" ? `${points[1] === "Added" ? "जोड़े" : "घटाए"} ${points[2]} अंक` : `${points[1] === "Added" ? "Adicionou" : "Reduziu"} ${points[2]} pontos`;
  const componentPoints = value.match(/^([\d.]+) component points$/);
  if (componentPoints) return locale === "hi" ? `${componentPoints[1]} घटक अंक` : `${componentPoints[1]} pontos do componente`;
  const representative = value.match(/^Anonymized representative summary (\d+)$/);
  if (representative) return locale === "hi" ? `गुमनाम प्रतिनिधि सारांश ${representative[1]}` : `Resumo representativo anonimizado ${representative[1]}`;
  const influence = value.match(/^#(\d+) influence$/);
  if (influence) return locale === "hi" ? `#${influence[1]} प्रभाव` : `Influência nº ${influence[1]}`;
  return value;
}

function translateFactorPhrase(value: string, locale: Exclude<PublicLocale, "en">): string {
  let result = value;
  for (const [source, translated] of Object.entries(translations)) {
    const replacement = translated[locale === "hi" ? 0 : 1];
    result = result.replaceAll(source.toLowerCase(), replacement.toLowerCase());
  }
  if (locale === "hi") return result.replaceAll(", and ", ", और ").replaceAll(" and ", " और ");
  return result.replaceAll(", and ", " e ").replaceAll(" and ", " e ");
}
